import { html } from 'lit-html';
import { action } from '@storybook/addon-actions';


export default {
  title: 'Components/Branch Input',
  component: 'bfl-branch-input',
  tags: ['autodocs'],
  argTypes: {
    value: {
      control: 'text',
      description: 'It holds the value of branch'
    },
    customErrorMessage: {
      control: 'text',
      description: 'Text to display the custom error message',
      defaultValue: '',
    },
    isRequired: {
      control: 'boolean',
      description: 'Helps  user to state whether the field is required or not',
      defaultValue: false,
    },
    hasCustomError: {
      control: 'boolean',
      description: 'States whether the field has custom error',
      defaultValue: false,
    },
    name: {
      control: 'text',
      description: 'Holds the name of input'
    },
    label: {
      control: 'text',
      description: 'Text to display the label for branch input field'
    },
    placeholder: {
      control: 'text',
      description: 'Text to display as placeholder of branch',
      defaultValue: 'Please select the branch',
    },
  },
};

const Template = ({label,value, customErrorMessage,isRequired,hasCustomError,name,placeholder,text }) => html`
  <bfl-branch-input
    label=${label}
    value=${value}
    customErrorMessage=${customErrorMessage}
    isRequired=${isRequired}
    hasCustomError=${hasCustomError}
    name=${name}
    placeholder=${placeholder}
    @inputChanged="${action('inputChanged')}"
  >
  <call-back-link text=${text}></call-back-link>  
  </bfl-branch-input>
`;

export const Default = Template.bind({});
Default.args = {
  isRequired: false,
  hasCustomError:false,
  value: 'Branch value text',
};

export const WithPlaceholderLabel = Template.bind({});
WithPlaceholderLabel.args = {
  isRequired: false,
  hasCustomError:false,
  placeholder:'Select branch',
  label: 'Branch label text',
};


export const test = Template.bind({});
test.args = {
  ...Default.args,
  label: 'Branch Name text',
  branchValue: 'Branch value text',
  text:'Change',
  customErrorMessage:'custom error'
};




